+
+	{{provider.name}}data "github.com/{{owner}}/terraform-provider-{{provider.name}}/internal/data"
+	{{provider.name}}resource "github.com/{{owner}}/terraform-provider-{{provider.name}}/internal/resource"
+	{{provider.name}}utils "github.com/{{owner}}/terraform-provider-{{provider.name}}/internal/utils"
+)
+
+// Ensure the implementation satisfies the expected interfaces.
+var (
+	_ provider.Provider = &{{provider.name}}Provider{}
+)
+
+// New is a helper function to simplify provider server and testing implementation.
+func New(version string) func() provider.Provider {
+	return func() provider.Provider {
+		return &{{provider.name}}Provider{
+			version: version,
+		}
+	}
+}
+
+// {{provider.name}}Provider is the provider implementation.
+type {{provider.name}}Provider struct {
+	// version is set to the provider version on release, "dev" when the
+	// provider is built and ran locally, and "test" when running acceptance
+	// testing.
+	version string
+}
+
+// {{provider.name}}ProviderModel maps provider schema data to a Go type.
+type {{provider.name}}ProviderModel struct {
+    {{#provider.model}}
+	{{camelcase}} types.{{type}} `tfsdk:"{{snakecase}}"`
+    {{/provider.model}}
+}
+
+// Metadata returns the provider type name.
+func (p *{{provider.name}}Provider) Metadata(_ context.Context, _ provider.MetadataRequest, resp *provider.MetadataResponse) {
+	resp.TypeName = "{{provider.name}}"
+	resp.Version = p.version
+}
+
+// Schema defines the provider-level schema for configuration data.
+{{!a schema describing what data is available in the data source's configuration and state.}}
+func (p *{{provider}}Provider) Schema(_ context.Context, _ provider.SchemaRequest, resp *provider.SchemaResponse) {
+	resp.Schema = schema.Schema{
+		Attributes: map[string]schema.Attribute{
+            {{#schema}}
+			"{{cammelcase}}": schema.{{type}}Attribute{
+				Optional:  true,
+				Sensitive: true,
+			},
+		    {{/schema}}
+		},
+	}
+}
+
+// Configure prepares a {{provider}} API client for data sources and resources.
+func (p *{{provider}}Provider) Configure(ctx context.Context, req provider.ConfigureRequest, resp *provider.ConfigureResponse) {
+	tflog.Info(ctx, "Configuring {{provider}} client")
+	// Retrieve provider data from configuration
+	var config {{provider}}ProviderModel
+	diags := req.Config.Get(ctx, &config)
+	resp.Diagnostics.Append(diags...)
+	if resp.Diagnostics.HasError() {
+		return
+	}
+
+	// If practitioner provided a configuration value for any of the
+	// attributes, it must be a known value.
+
+	if config.ApiKey.IsUnknown() {
+		resp.Diagnostics.AddAttributeError(
+			path.Root("api_key"),
+			"Unknown Addy.io API Key",
+			"The provider cannot create the Addy API client as there is an unknown configuration value for the Addy API key. "+
+				"Either target apply the source of the value first, set the value statically in the configuration, or use the ADDY_API_KEY environment variable.",
+		)
+	}
+
+	if resp.Diagnostics.HasError() {
+		return
+	}
+
+	// Default values to environment variables, but override
+	// with Terraform configuration value if set.
+
+	{{#env}}
+	{{snakecase}} := os.Getenv("{{var}}")
+	{{/env}}
+
+	if !config.ApiKey.IsNull() {
+		api_key = config.ApiKey.ValueString()
+	}
+
+	// If any of the expected configurations are missing, return
+	// errors with provider-specific guidance.
+
+	if api_key == "" {
+		resp.Diagnostics.AddAttributeError(
+			path.Root("api_key"),
+			"Missing Addy API Key",
+			"The provider cannot create the Addy API client as there is a missing or empty value for the Addy API key. "+
+				"Set the key value in the configuration or use the ADDY_API_KEY environment variable. "+
+				"If either is already set, ensure the value is not empty.",
+		)
+	}
+
+	if resp.Diagnostics.HasError() {
+		return
+	}
+
+	// Create a new Addy client using the configuration values
+	client, err := {{provider}}utils.NewClient(ctx)
+	if err != nil {
+		resp.Diagnostics.AddError(
+			"Unable to Create Addy API Client",
+			"An unexpected error occurred when creating the Addy API client. "+
+				"If the error is not clear, please contact the provider developers.\n\n"+
+				"Addy Client Error: "+err.Error(),
+		)
+		return
+	}
+
+	// Make the {{Addy}} client available during DataSource and Resource
+	// type Configure methods.
+	resp.DataSourceData = &{{provider}}data.DataSourceData{
+	    {{#datasources}}
+		{{camelcase}}: {{snakecase}},
+		{{#datasources}}
+	}
+	resp.ResourceData = client
+}
+
+// DataSources defines the data sources implemented in the provider.
+func (p *{{provider}}Provider) DataSources(_ context.Context) []func() datasource.DataSource {
+	return []func() datasource.DataSource{
+        {{#provider.datasources}}
+    	{{provider.name}}data.New{{.}}DataSource,
+    	{{/provider.datasources}}
+	}
+}
+
+// Resources defines the resources implemented in the provider.
+func (p *{{provider.name}}Provider) Resources(_ context.Context) []func() resource.Resource {
+	return []func() resource.Resource{
+	    {{#provider.resources}}
+		{{provider.name}}resource.New{{.}}Resource,
+        {{/provider.resources}}
+	}
+}

